svg.script:
"use strict";
const svg = document.getElementById("sms-setup-guide");
const current = svg.querySelector("#current");
const incoming = svg.querySelector("#incoming");
incoming.replaceChildren(...Array.from(current.children, child => child.cloneNode(true)));

const xiaomi = svg.dataset.guide === "xiaomi";
const screens = xiaomi ? [
  ["设置", "应用设置"],
  ["应用设置", "空叶键盘"],
  ["应用信息", "权限管理", "空叶键盘"],
  ["权限管理", "其他权限", "短信"],
  ["其他权限", "通知类短信", "写入剪贴板"],
  ["通知类短信", "始终允许", "拒绝", "", true],
] : [
  ["系统设置", "应用"],
  ["应用", "空叶键盘"],
  ["应用信息", "权限", "空叶键盘"],
  ["应用权限", "短信"],
  ["短信权限", "允许", "拒绝", "", true],
  ["短信验证码", "短信验证码自动复制", "", "", true],
];

function elements(group) {
  return Object.fromEntries([...group.children].filter(el => el.hasAttribute("class"))
    .map(el => [el.getAttribute("class"), el]));
}
const active = elements(current);
const next = elements(incoming);
const stepMs = 1750;
const duration = stepMs * screens.length;
const clamp = value => Math.max(0, Math.min(1, value));
const ease = value => (1 - Math.cos(Math.PI * clamp(value))) / 2;
let position = 0, frame = 0, last = 0;
let pausedByUser = matchMedia("(prefers-reduced-motion: reduce)").matches;

function draw(scene, screen, elapsed) {
  const [title, label, upper = "", lower = "", choice = false] = screen;
  scene.title.textContent = title;
  scene.label.textContent = label;
  scene.upper.textContent = upper;
  scene.lower.textContent = lower;
  const tap = 880;
  const x = choice ? 623 : 515;
  const enter = ease((elapsed - 420) / 280);
  const leave = 1 - ease((elapsed - 1130) / 180);
  const pulse = elapsed >= tap && elapsed <= tap + 360 ? Math.sin(Math.PI * (elapsed - tap) / 360) : 0;
  scene.next.setAttribute("opacity", choice ? 0 : 1);
  scene.selected.setAttribute("opacity", choice ? 1 : 0);
  scene.selected.setAttribute("fill", choice && elapsed >= tap ? "#ACCENT" : "none");
  scene.selected.setAttribute("stroke", choice && elapsed >= tap ? "#ACCENT" : "#MUTED");
  scene.press.setAttribute("opacity", .13 * pulse);
  scene.ring.setAttribute("cx", x);
  scene.ring.setAttribute("opacity", .65 * pulse);
  scene.ring.setAttribute("r", 16 + 14 * clamp((elapsed - tap) / 360));
  scene.pointer.setAttribute("opacity", enter * leave);
  scene.pointer.setAttribute("transform", "translate(" + (x + 22 * (1 - enter)) + " " + (237 + 32 * (1 - enter)) + ") rotate(-15) scale(3.25)");
}
function render(time) {
  position = ((time % duration) + duration) % duration;
  const index = Math.floor(position / stepMs);
  const elapsed = position % stepMs;
  const slide = ease((elapsed - 1380) / (stepMs - 1380));
  draw(active, screens[index], elapsed);
  draw(next, screens[(index + 1) % screens.length], 0);
  current.setAttribute("transform", "translate(" + (-704 * slide) + " 0)");
  incoming.setAttribute("transform", "translate(" + (704 * (1 - slide)) + " 0)");
}
function advance(now) {
  if (last) render(position + now - last);
  last = now;
  frame = requestAnimationFrame(advance);
}
function pause() {
  cancelAnimationFrame(frame);
  frame = 0;
  last = 0;
}
function resume() {
  if (!frame) frame = requestAnimationFrame(advance);
}
function updatePlayback() {
  svg.setAttribute("aria-label", pausedByUser ? "继续设置流程动画" : "暂停设置流程动画");
  if (pausedByUser || document.hidden) pause();
  else resume();
}
function togglePlayback() {
  pausedByUser = !pausedByUser;
  updatePlayback();
}
window.smsGuide = { render, pause, resume };
svg.addEventListener("click", togglePlayback);
svg.addEventListener("keydown", event => {
  if (event.repeat || (event.key !== "Enter" && event.key !== " ")) return;
  event.preventDefault();
  togglePlayback();
});
document.addEventListener("visibilitychange", updatePlayback);
render(0);
updatePlayback();
